"""AZSX-owned event text with independently configurable AZSXUI rendering."""
from pathlib import Path
import unittest
from test_official_party_lua import STUB,LuaRuntime
ROOT=Path(__file__).resolve().parents[1]
@unittest.skipUnless(LuaRuntime,"Explicit AZSXUI profile requires Lua 5.1")
class EventTests(unittest.TestCase):
    def setUp(self):
        self.lua=LuaRuntime();self.lua.execute(STUB);self.lua.execute('local create=CreateFrame;function CreateFrame(kind,...)local f=create(kind,unpack(arg));function f:GetFrameLevel()return self.level or 5 end;if kind=="Font"then function f:SetTextColor(r,g,b)self.textColor={r,g,b}end;function f:GetStringHeight()return (self.fontSize or 12)*1.2 end end;return f end');self.lua.execute("SlashCmdList={}")
        self.lua.execute('view={epoch="1",own="11",owner={discovery={event=1,title="AZSX supplies title",icon="Interface/Icons/INV_Crate_01",reward="AZSX reward wording",note="AZSX exact receipt",color={1,.5,0}},ritual={event=2,held=700,inside=true,maximum=2000,title="AZSX ritual title",note="AZSX progress wording"}},blessing={boss=1,title="AZSX fortune title",icon="Interface/Icons/INV_Misc_Orb_02",reward="AZSX exact fortune",note="AZSX fortune note",color={1,1,1}}};function AZSX_GetAPIVersion()return 1,0 end;function AZSX_GetState()return {available=true,session={epoch=view.epoch,recipientGUID=view.own},data={discovery=view.owner.discovery,sayge=view.owner.ritual,fortune=view.blessing},texts={supplies=view.owner.discovery,sayge=view.owner.ritual,fortune=view.blessing}}end;function tick()now=now+.2;objects.AZSXUIEventsController.scripts.OnUpdate()end')
        self.lua.execute((ROOT/'addons/AZSXUI/Theme.lua').read_text());self.lua.execute((ROOT/'addons/AZSXUI/Events.lua').read_text());self.lua.execute('tick()')
    def run_lua(self,s):self.lua.execute(s)
    def test_engineering_badge_and_single_reward_toast_follow_local_api(self):
        self.run_lua('''view.engineering={event=1,kind="grenade",nextTrigger=450,remaining=0,title="Goblin Stun Grenade",description="Native projectile",reward="Goblin Stun Grenade equipped",duration="Until the end of the run",icon="Interface/Icons/INV_Gizmo_01"}
local original=AZSX_GetState
function AZSX_GetState(...)local s=original(unpack(arg));s.data.engineering=view.engineering;s.texts.engineering=view.engineering;return s end
tick();assert(objects.AZSXUIEngineeringBadge:IsShown() and objects.AZSXUIEngineeringBadge.icon.texture==view.engineering.icon and objects.AZSXUIEngineeringBadge.anchor[2]==UIParent)
assert(objects.AZSXUIEngineeringRewardToast:IsShown() and objects.AZSXUIEngineeringRewardToast.reward.text==view.engineering.reward)
now=now+6;tick();assert(not objects.AZSXUIEngineeringRewardToast:IsShown())
tick();assert(not objects.AZSXUIEngineeringRewardToast:IsShown())
view.engineering.nextTrigger=3000;tick();assert(objects.AZSXUIEngineeringBadge.scale>1)
now=now+2;tick();assert(objects.AZSXUIEngineeringBadge.scale==1)
view.engineering=nil;tick();assert(not objects.AZSXUIEngineeringBadge:IsShown())''')
    def test_sale_uses_exact_gold_and_native_coin_then_clears_for_a_buff(self):
        self.run_lua('view.owner.discovery.event=2;view.owner.discovery.gold=25;view.owner.discovery.note="Sold for 25 gold";now=now+4;tick();local t=objects.AZSXSupplyDiscoveryToast;assert(t.note.text=="Sold for 25" and t.coin:IsShown() and t.coin.texture=="Interface\\\\MoneyFrame\\\\UI-GoldIcon");view.owner.discovery.event=3;view.owner.discovery.gold=0;view.owner.discovery.note="+10% damage - 60 seconds";now=now+4;tick();assert(not t.coin:IsShown() and string.find(t.note.text,"Duration:",1,true))')
    def test_popups_use_classic_wow_backdrop_and_font(self):
        self.run_lua('local f=objects.AZSXSupplyDiscoveryToast;assert(f.backdrop.bgFile=="Interface\\\\DialogFrame\\\\UI-DialogBox-Background" and f.backdrop.edgeFile=="Interface\\\\DialogFrame\\\\UI-DialogBox-Border");assert(f.title.fontSize==12 and string.find(f.title.font,"FRIZQT__",1,true))')
    def test_all_semantic_text_is_displayed_verbatim_from_azsx(self):
        self.run_lua('assert(objects.AZSXSupplyDiscoveryToast.title.text==view.owner.discovery.title and objects.AZSXSupplyDiscoveryToast.reward.text==view.owner.discovery.reward and objects.AZSXSupplyDiscoveryToast.note.text==view.owner.discovery.note);assert(objects.AZSXDarkmoonBlessingToast.reward.text==view.blessing.reward and objects.AZSXDarkmoonBlessingToast.note.text==view.blessing.note);assert(objects.AZSXSaygeTrialProgress.title.text==view.owner.ritual.title and objects.AZSXSaygeTrialProgress.time.text=="13.0 s" and objects.AZSXSaygeTrialProgress.note.text=="")')
    def test_bonus_numbers_are_green_labels_white_and_time_stays_inside_track(self):
        self.run_lua('assert(AZSXUI_FormatBonus("+10% damage, +2 targets")=="|cff1eff00+10%|r damage, |cff1eff00+2|r targets");assert(AZSXUI_FormatBonus("-2.5% haste")=="|cff1eff00-2.5%|r haste");local f=objects.AZSXSaygeTrialProgress;assert(f.time.anchor[1]=="RIGHT" and f.title.anchor[1]=="LEFT" and f.time.anchor[2]==f.title.anchor[2]);view.owner.ritual.allInside=false;tick();assert(f.note.text=="Waiting for all players" and f.time.text=="13.0 s")')
    def test_actual_reward_widgets_keep_labels_white_and_supply_rarity(self):
        self.run_lua('view.blessing.boss=2;view.blessing.reward="+12% Luck";view.blessing.color={.12,1,0};view.owner.discovery.event=2;view.owner.discovery.note="+14% haste - 60 seconds";now=now+4;tick();local fortune=objects.AZSXDarkmoonBlessingToast;local supply=objects.AZSXSupplyDiscoveryToast;assert(fortune.reward.text=="|cff1eff00+12%|r Luck" and fortune.reward.textColor[1]==1 and fortune.reward.textColor[2]==1 and fortune.reward.textColor[3]==1);assert(supply.note.text=="|cff1eff00+14%|r haste\\nDuration: |cff1eff0060|r seconds" and supply.note.textColor[1]==1 and supply.note.textColor[2]==1 and supply.note.textColor[3]==1);assert(supply.reward.text==view.owner.discovery.reward and supply.reward.textColor[2]==.5)')
    def test_position_scale_opacity_visibility_and_reset_are_per_widget(self):
        self.run_lua('assert(AZSXUI_ConfigureWidget("supplies","position","120","-210"));assert(AZSXUI_ConfigureWidget("supplies","scale","1.4"));assert(AZSXUI_ConfigureWidget("supplies","opacity","0.45"));local f=objects.AZSXSupplyDiscoveryToast;assert(math.abs(f.anchor[4]-120/1.4)<.001 and f.anchor[2]==objects.AZSXUIEventAnchor and f.scale==1.4 and f.alpha==.45);assert(objects.AZSXDarkmoonBlessingToast.alpha==1);assert(AZSXUI_ConfigureWidget("sayge","show","off"));assert(not objects.AZSXSaygeTrialProgress.shown and view.owner.ritual.held==700);assert(AZSXUI_ConfigureWidget("sayge","show","on"));assert(objects.AZSXSaygeTrialProgress.shown);assert(AZSXUI_ConfigureWidget("supplies","reset"));assert(f.anchor[4]==0 and f.anchor[5]==-66 and f.scale==1 and f.alpha==1)')
    def test_slash_commands_apply_immediately_to_persistent_preferences(self):
        self.lua.execute((ROOT/'addons/AZSXUI/AZSXUI.lua').read_text())
        self.run_lua('SlashCmdList.AZSXUI("widget supplies position 90 -190");SlashCmdList.AZSXUI("widget supplies opacity 0.6");assert(objects.AZSXSupplyDiscoveryToast.anchor[4]==90 and objects.AZSXSupplyDiscoveryToast.alpha==.6);saved=AZSXUIDB.widgets;SlashCmdList.AZSXUI("widget sayge show off");assert(not objects.AZSXSaygeTrialProgress.shown);SlashCmdList.AZSXUI("widget sayge reset");assert(objects.AZSXSaygeTrialProgress.shown);SlashCmdList.AZSXUI("widget sayge scale bad");assert(AZSXUIDB.widgets.sayge.scale==1)')
    def test_shared_anchor_stacks_scaled_visible_widgets_and_tracks_hud_top(self):
        self.run_lua('local a=objects.AZSXUIEventAnchor;assert(a.anchor[2]==UIParent and a.anchor[4]==0 and a.anchor[5]==-125);local sayge=objects.AZSXSaygeTrialProgress;local supply=objects.AZSXSupplyDiscoveryToast;local fortune=objects.AZSXDarkmoonBlessingToast;assert(sayge.anchor[2]==a and sayge.anchor[5]==0 and supply.anchor[5]==-66 and fortune.anchor[5]==-158);AZSXUI_ConfigureWidget("sayge","scale","2");assert(supply.anchor[5]==-120 and fortune.anchor[5]==-212);AZSXUI_ConfigureWidget("sayge","show","off");assert(supply.anchor[5]==0 and fortune.anchor[5]==-92);assert(AZSXUI_ConfigureWidget("anchor","position","10","-100"));assert(a.anchor[4]==10 and a.anchor[5]==-100)')
    def test_previous_default_anchor_migrates_once_custom_positions_and_reset_are_preserved(self):
        self.run_lua('AZSXUIDB={eventAnchor={x=0,y=-85}};tick();assert(AZSXUIDB.eventAnchor.y==-125);AZSXUI_ConfigureWidget("anchor","position","0","-85");tick();assert(AZSXUIDB.eventAnchor.y==-85);AZSXUIDB={eventAnchor={x=10,y=-85}};tick();assert(AZSXUIDB.eventAnchor.x==10 and AZSXUIDB.eventAnchor.y==-85);AZSXUI_ConfigureWidget("anchor","reset");assert(AZSXUIDB.eventAnchor.y==-125)')
    def test_compact_popup_grows_for_wrapped_text_and_stack_uses_real_height(self):
        self.run_lua('local f=objects.AZSXSupplyDiscoveryToast;assert(f:GetWidth()==320 and f:GetHeight()==80 and f.icon:GetWidth()==32);function f.title:GetStringHeight()return 14 end;function f.reward:GetStringHeight()return 36 end;function f.note:GetStringHeight()return 28 end;tick();assert(f:GetHeight()==110);assert(objects.AZSXDarkmoonBlessingToast.anchor[5]==f.anchor[5]-110-12)')
    def test_fortune_does_not_replay_on_missing_data_new_epoch_or_new_trial(self):
        self.run_lua('now=now+10;tick();assert(not objects.AZSXDarkmoonBlessingToast.shown);local getter=AZSX_GetState;AZSX_GetState=nil;tick();AZSX_GetState=getter;view.epoch="2";view.owner.ritual.event=3;tick();assert(not objects.AZSXDarkmoonBlessingToast.shown);view.blessing.boss=2;tick();assert(objects.AZSXDarkmoonBlessingToast.shown)')
    def test_fortune_popup_is_not_rearmed_by_choice_or_transient_clock_rollback(self):
        self.run_lua('phase="choosing";for i=1,40 do tick()end;phase="playing";tick();assert(not objects.AZSXDarkmoonBlessingToast.shown);function AZS_GetRunTime()return 0 end;tick();assert(not objects.AZSXDarkmoonBlessingToast.shown);view.owner.ritual.event=99;tick();assert(not objects.AZSXDarkmoonBlessingToast.shown)')
    def test_fortune_receipt_announces_identical_rewards_once_and_defers_new_receipts(self):
        self.run_lua('view.blessing.event=101;tick();now=now+8;tick();assert(not objects.AZSXDarkmoonBlessingToast.shown);view.blessing.best=9000;view.epoch="2";tick();assert(not objects.AZSXDarkmoonBlessingToast.shown);phase="choosing";view.blessing.event=102;tick();phase="playing";tick();assert(objects.AZSXDarkmoonBlessingToast.shown);now=now+8;tick();assert(not objects.AZSXDarkmoonBlessingToast.shown)')
    def test_old_absolute_positions_migrate_to_relative_offsets(self):
        self.run_lua('AZSXUIDB={widgets={supplies={x=20,y=-180},fortune={y=-260},sayge={y=-75}}};tick();assert(AZSXUIDB.widgetLayoutVersion==2 and AZSXUIDB.widgets.supplies.y==-40 and AZSXUIDB.widgets.fortune.y==0 and AZSXUIDB.widgets.sayge.y==0)')
    def test_invalid_inputs_do_not_change_valid_preferences(self):
        self.run_lua('assert(AZSXUI_ConfigureWidget("sayge","scale","1.5"));for _,v in ipairs({"0","3","nan","inf","bad"})do assert(not AZSXUI_ConfigureWidget("sayge","scale",v))end;assert(not AZSXUI_ConfigureWidget("sayge","opacity","2"));assert(not AZSXUI_ConfigureWidget("sayge","position","5000","0"));assert(not AZSXUI_ConfigureWidget("other","show","off"));assert(AZSXUIDB.widgets.sayge.scale==1.5)')
    def test_saved_corrupt_preferences_are_repaired(self):
        self.run_lua('AZSXUIDB={widgets={sayge={scale=0/0,opacity=math.huge,x="bad",visible="yes"}}};tick();local p=AZSXUIDB.widgets.sayge;assert(p.scale==1 and p.opacity==1 and p.x==0 and p.visible==true)')
    def test_visibility_consumes_notifications_without_replay(self):
        self.run_lua('AZSXUI_ConfigureWidget("supplies","show","off");now=now+5;tick();AZSXUI_ConfigureWidget("supplies","show","on");assert(not objects.AZSXSupplyDiscoveryToast.shown);view.owner.discovery.event=2;tick();assert(objects.AZSXSupplyDiscoveryToast.shown)')
    def test_missing_bridge_hides_all_widgets_without_fabricating_text(self):
        self.run_lua('AZSX_GetState=nil;tick();assert(not objects.AZSXSupplyDiscoveryToast.shown and not objects.AZSXDarkmoonBlessingToast.shown and not objects.AZSXSaygeTrialProgress.shown)')
    def test_unsupported_public_major_hides_views_without_using_legacy_bridge(self):
        self.run_lua('function AZSX_GetEventPresentation()error("legacy bridge used")end;function AZSX_GetAPIVersion()return 2,0 end;tick();assert(not objects.AZSXSupplyDiscoveryToast.shown and not objects.AZSXDarkmoonBlessingToast.shown and not objects.AZSXSaygeTrialProgress.shown)')
    def test_new_recipient_retires_old_queue_and_progress_identity(self):
        self.run_lua('view.owner.discovery={event=2,title="Queued old",icon="icon",reward="Old",note="Old",color={1,1,1}};tick();view.epoch="2";view.own="22";view.owner.discovery={event=1,title="New owner",icon="icon",reward="New owner",note="New",color={1,1,1}};view.owner.ritual.held=100;tick();assert(objects.AZSXSupplyDiscoveryToast.reward.text=="New owner");assert(objects.AZSXSaygeTrialProgress.rendered==100)')
if __name__=='__main__':unittest.main()
